  // spellchecker: ignore-next-line
  member    hrm_time_track_members    @relation(fields: [hrm_time_track_member_id], references: [id], onDelete: Cascade, map: "hrm_time_track_timesheet_snapshots_hrm_time_track_memb_30ae2943")

  //----
  // INDEXES
  //----
  // spellchecker: ignore-next-line
  @@index([hrm_time_track_member_id], map: "hrm_time_track_timesheet_snapshots_hrm_time_track_memb_bdf6a347")
  // spellchecker: ignore-next-line
