  TestValidator.equals(
    "name updated",
    updatedOrganization.name,
    updateBody.name,
  );
  TestValidator.equals(
    "description updated",
    updatedOrganization.description,
    updateBody.description,
  );
  TestValidator.equals(
    "logo updated",
    updatedOrganization.logo,
    updateBody.logo,
