  TestValidator.equals(
    "re-assignment employee matches",
    reAssignedMember.employee.id,
    employee.id,
  );
  TestValidator.equals(
    "re-assignment project matches",
    reAssignedMember.project.id,
    project.id,
  );
  TestValidator.equals(
    "re-assignment role is member",
    reAssignedMember.role,
