    // Verify required fields exist
    TestValidator.predicate(`task ${task.id} has id`, task.id !== undefined);
    TestValidator.predicate(
      `task ${task.id} has title`,
      task.title !== undefined,
    );
    TestValidator.predicate(
      `task ${task.id} has priority`,
