/**
 * Test that an authenticated member can filter tasks by status and priority values.
 *
 * Validates the task listing endpoint's filtering capabilities by creating a comprehensive test environment with multiple tasks having different status and priority combinations. The test verifies that filtering by status, priority, or both criteria returns the correct subset of tasks.
 *
 * Special attention is given to verifying that the filter parameters correctly narrow down the task list, that pagination metadata reflects the filtered results, and that empty result sets are handled properly with valid pagination information.
 *
 * 1. Register and authenticate a member account.
 * 2. Create an organization for the test context.
 * 3. Create an employee record linking the member to the organization.
 * 4. Create a project within the organization.
 * 5. Assign the employee as a project member with project-lead role.
 * 6. Create multiple tasks with various status and priority combinations.
 * 7. Test status-only filtering by querying for in-progress tasks.
 * 8. Test priority-only filtering by querying for urgent priority tasks.
 * 9. Test combined filtering with both status and priority parameters.
 * 10. Validate that all filter results contain only matching tasks.
 */
export async function test_api_task_list_with_status_priority_filter(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register and authenticate member
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "1234",
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IHrmTimeTrackMember.IJoin,
  });
  typia.assert(memberAuth);
  // 2. Create organization
  const organization =
    await generate_random_hrm_time_track_member_organizations_create(
      memberConnection,
      {},
    );
  typia.assert(organization);
  // 3. Create employee record
  const employee = await generate_random_hrm_time_track_member_employees_create(
    memberConnection,
    {
      body: {
        hrm_time_track_member_id: memberAuth.id,
        position: "Software Engineer",
        employment_type: "full-time",
        hire_date: new Date().toISOString(),
        status: "active",
      },
    },
  );
  typia.assert(employee);
  // 4. Create project
  const project = await generate_random_hrm_time_track_member_projects_create(
    memberConnection,
    {},
  );
  typia.assert(project);
  // 5. Assign employee as project member
  const projectMember =
    await generate_random_hrm_time_track_member_projects_members_create(
      memberConnection,
      {
        params: { projectId: project.id },
        body: {
          employee_id: employee.id,
          role: "project-lead",
        },
      },
    );
  typia.assert(projectMember);
  // 6. Create multiple tasks with various status and priority combinations
  const tasks: IHrmTimeTrackTask[] = [];
  // Task 1: in-progress, urgent
  const task1 = await generate_random_hrm_time_track_member_tasks_create(
    memberConnection,
    {
      body: {
        hrm_time_track_project_id: project.id,
        title: "Critical bug fix",
        status: "in-progress",
        priority: "urgent",
      },
    },
  );
  typia.assert(task1);
  tasks.push(task1);
  // Task 2: in-progress, high
  const task2 = await generate_random_hrm_time_track_member_tasks_create(
    memberConnection,
    {
      body: {
        hrm_time_track_project_id: project.id,
        title: "Feature implementation",
        status: "in-progress",
        priority: "high",
      },
    },
  );
  typia.assert(task2);
  tasks.push(task2);
  // Task 3: open, urgent
  const task3 = await generate_random_hrm_time_track_member_tasks_create(
    memberConnection,
    {
      body: {
        hrm_time_track_project_id: project.id,
        title: "Security patch",
        status: "open",
        priority: "urgent",
      },
    },
  );
  typia.assert(task3);
  tasks.push(task3);
  // Task 4: completed, medium
  const task4 = await generate_random_hrm_time_track_member_tasks_create(
    memberConnection,
    {
      body: {
        hrm_time_track_project_id: project.id,
        title: "Documentation update",
        status: "completed",
        priority: "medium",
      },
    },
  );
  typia.assert(task4);
  tasks.push(task4);
  // Task 5: open, low
  const task5 = await generate_random_hrm_time_track_member_tasks_create(
    memberConnection,
    {
      body: {
        hrm_time_track_project_id: project.id,
        title: "UI polish",
        status: "open",
        priority: "low",
      },
    },
  );
  typia.assert(task5);
  tasks.push(task5);
  // Task 6: in-progress, urgent (second urgent in-progress task)
  const task6 = await generate_random_hrm_time_track_member_tasks_create(
    memberConnection,
    {
      body: {
        hrm_time_track_project_id: project.id,
        title: "Performance optimization",
        status: "in-progress",
        priority: "urgent",
      },
    },
  );
  typia.assert(task6);
  tasks.push(task6);
  // 7. Test status-only filtering: in-progress
  const statusFilterResult =
    await api.functional.hrmTimeTrack.member.tasks.index(memberConnection, {
      body: {
        status: "in-progress",
      } satisfies IHrmTimeTrackTask.IRequest,
    });
  typia.assert(statusFilterResult);
  // Validate all returned tasks have in-progress status
  TestValidator.predicate(
    "status filter returns correct count",
    statusFilterResult.data.length === 3,
  );
  for (const task of statusFilterResult.data) {
    TestValidator.equals(
      "task status is in-progress",
      task.status,
      "in-progress",
    );
  }
  // 8. Test priority-only filtering: urgent
  const priorityFilterResult =
    await api.functional.hrmTimeTrack.member.tasks.index(memberConnection, {
      body: {
        priority: "urgent",
      } satisfies IHrmTimeTrackTask.IRequest,
    });
  typia.assert(priorityFilterResult);
  // Validate all returned tasks have urgent priority
  TestValidator.predicate(
    "priority filter returns correct count",
    priorityFilterResult.data.length === 3,
  );
  for (const task of priorityFilterResult.data) {
    TestValidator.equals("task priority is urgent", task.priority, "urgent");
  }
  // 9. Test combined filtering: in-progress AND urgent
  const combinedFilterResult =
    await api.functional.hrmTimeTrack.member.tasks.index(memberConnection, {
      body: {
        status: "in-progress",
        priority: "urgent",
      } satisfies IHrmTimeTrackTask.IRequest,
    });
  typia.assert(combinedFilterResult);
  // Validate all returned tasks match both criteria
  TestValidator.predicate(
    "combined filter returns correct count",
    combinedFilterResult.data.length === 2,
  );
  for (const task of combinedFilterResult.data) {
    TestValidator.equals(
      "task status is in-progress",
      task.status,
      "in-progress",
    );
    TestValidator.equals("task priority is urgent", task.priority, "urgent");
  }
  // 10. Test empty result set: closed status (no tasks with this status)
  const emptyFilterResult =
    await api.functional.hrmTimeTrack.member.tasks.index(memberConnection, {
      body: {
        status: "closed",
      } satisfies IHrmTimeTrackTask.IRequest,
    });
  typia.assert(emptyFilterResult);
  // Validate empty result set has correct pagination
  TestValidator.equals(
    "empty filter returns zero records",
    emptyFilterResult.data.length,
    0,
  );
  TestValidator.equals(
    "empty filter pagination records is zero",
    emptyFilterResult.pagination.records,
    0,
  );
}

