    billable: true,
    page: 1,
    limit: 20,
  } satisfies IHrmTimeTrackTimelog.IRequest;
  const billableResult =
    await api.functional.hrmTimeTrack.member.timelogs.index(memberConnection, {
      body: billableFilter,
