  public async create(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IHrmTimeTrackTimelog.ICreate,
  ): Promise<IHrmTimeTrackTimelog> {
    try {
      return await postHrmTimeTrackMemberTimelogs({
        member,
        body,
      });
